// Extract surah query or number from message
const raw = ($json.body?.message || '').toLowerCase();
const isTafsir = raw.includes('tafsir');

const surahMap = {
  'al-fatihah': 1, 'fatihah': 1, 'al-baqarah': 2, 'baqarah': 2,
  'ali imran': 3, 'an-nisa': 4, 'al-maidah': 5, 'al-kahf': 18,
  'kahfi': 18, 'maryam': 19, 'taha': 20, 'ya-sin': 36, 'yasin': 36,
  'ar-rahman': 55, 'rahman': 55, 'al-waqiah': 56, 'waqiah': 56,
  'al-mulk': 67, 'mulk': 67, 'an-naba': 78, 'al-ikhlas': 112,
  'al-falaq': 113, 'an-nas': 114
};

let surahNo = 1;
const numMatch = raw.match(/\b([1-9]|[1-9]\d|10\d|11[0-4])\b/);
if (numMatch) {
  surahNo = parseInt(numMatch[1], 10);
} else {
  for (const [name, num] of Object.entries(surahMap)) {
    if (raw.includes(name)) {
      surahNo = num;
      break;
    }
  }
}

return {
  json: {
    surahNo,
    isTafsir,
    apiUrl: isTafsir 
      ? `https://equran.id/api/v2/tafsir/${surahNo}`
      : `https://equran.id/api/v2/surat/${surahNo}`
  }
};

const isTafsir = $('Parse Surah Query').first().json.isTafsir;
const data = $json.data || {};

if (isTafsir) {
  const sampleTafsir = (data.tafsir || []).slice(0, 3);
  let content = `📜 **Tafsir Kemenag RI: QS. ${data.namaLatin} (${data.nomor}) - ${data.nama}**

`;
  content += `*Arti:* "${data.arti}" | *Golongan:* Surat ${data.tempatTurun} (${data.jumlahAyat} Ayat)

`;
  content += `> **Deskripsi:** ${(data.deskripsi || '').replace(/<[^>]+>/g, '')}

---

### 📖 Tafsir Ayat:

`;
  for (const t of sampleTafsir) {
    content += `**Ayat ke-${t.ayat}:**
${t.teks.substring(0, 250)}...

`;
  }
  return { json: { content, chips: [`📖 Baca Teks & Audio QS. ${data.namaLatin}`, '✨ Surat Al-Kahf (18)', '🌟 Surat Ya-Sin (36)', '👑 Surat Al-Mulk (67)'] } };
} else {
  const displayAyat = (data.ayat || []).slice(0, 4);
  let content = `📖 **QS. ${data.namaLatin} (${data.nomor}) - ${data.nama}**

`;
  content += `*Arti:* **"${data.arti}"** | *Tempat Turun:* **${data.tempatTurun}** (${data.jumlahAyat} Ayat)

---

### 📜 Cuplikan Ayat:

`;
  for (const a of displayAyat) {
    content += `**[Ayat ${a.nomorAyat}]**
> ### ${a.teksArab}
*${a.teksLatin}*

**Artinya:** "${a.teksIndonesia}"

`;
  }
  const audioUrl = data.audioFull ? Object.values(data.audioFull)[0] : '';
  if (audioUrl) {
    content += `🔊 **Audio Murottal:** [Dengarkan Tilawah Syaikh Abdullah Al-Juhany](${audioUrl})
`;
  }
  return { json: { content, chips: [`📜 Baca Tafsir QS. ${data.namaLatin}`, '✨ Baca Surat Al-Kahf (18)', '🌟 Baca Surat Ya-Sin (36)', '👑 Baca Surat Al-Mulk (67)'] } };
}
